-- =============================================================================
-- Liv Finder — geography seed  (countries)
-- =============================================================================
-- Plain SQL. Edit it directly; there is no generator behind it.
-- Regenerate with:  python3 db/tools/build_geo_seed.py
--
-- 250 sovereign states and dependent territories with ISO 3166-1
-- codes, dialling codes, currencies and native names.
-- `country_id` is set to the row's own id after insert — a
-- self-reference cannot be satisfied inside its own INSERT.
-- =============================================================================

SET NAMES utf8mb4;
SET autocommit = 0;


-- Countries are their own country ancestor.
UPDATE locations SET country_id = id WHERE level = 'country';


-- Localised country names. `languages` must be seeded first (010_reference.sql).

COMMIT;
SET autocommit = 1;
